class GetVersions(_GetVersions):

    @classmethod
    def _build_arguments_schema(cls, *args, **kwargs):
        args_schema = super()._build_arguments_schema(*args, **kwargs)
        args_schema.control_plane = AAZBoolArg(
            options=["--control-plane"],
            help="List the distinct Major.Minor (X.Y) versions available for the control plane. "
                 "Use one of these with 'cluster create --version', which takes an X.Y version.",
            default=False,
        )
        args_schema.node_pools = AAZBoolArg(
            options=["--node-pools"],
            help="List all available full X.Y.Z versions for node pools. "
                 "Use one of these with 'nodepool create --version', which requires a full X.Y.Z version.",
            default=False,
        )
        return args_schema

    def _output(self, *args, **kwargs):
        from azure.cli.core.azclierror import MutuallyExclusiveArgumentError
        from ._format import _parse_semver, _major_minor, _version_row

        result, next_link = super()._output(*args, **kwargs)

        control_plane = has_value(self.ctx.args.control_plane) and self.ctx.args.control_plane.to_serialized_data()
        node_pools = has_value(self.ctx.args.node_pools) and self.ctx.args.node_pools.to_serialized_data()

        if control_plane and node_pools:
            raise MutuallyExclusiveArgumentError(
                "--control-plane and --node-pools cannot be used together."
            )

        if not result:
            return result, next_link

        # Keep enabled versions only, ascending by semver.
        enabled = [v for v in result if v.get('properties', {}).get('enabled', True)]
        enabled.sort(key=lambda v: _parse_semver(v.get('name', '')))

        if control_plane:
            # Distinct Major.Minor (X.Y) versions, ascending. 'cluster create --version'
            # takes an X.Y version.
            rows = []
            seen = set()
            for v in enabled:
                xy = _major_minor(v.get('name', ''))
                if not xy or xy in seen:
                    continue
                seen.add(xy)
                row = _version_row(v)
                row['Name'] = xy
                rows.append(row)
        else:
            # Default (and --node-pools): all enabled full X.Y.Z versions, ascending.
            # 'nodepool create --version' requires a full X.Y.Z version, so the bare
            # 'get-versions' output matches the node-pools listing.
            rows = [_version_row(v) for v in enabled]

        return rows, next_link


